solution.code:
function missing(nums) {
  var n = nums.length;
  var expected = n * (n + 1) / 2;
  var actual = nums.reduce(function (a, b) {
    return a + b;
  }, 0);
  return expected - actual;
}

console.log(missing([9, 6, 4, 2, 3, 5, 7, 0, 1]));
